import { useEffect, useState } from 'react'
import type { ReactNode } from 'react'
import { backendFetch, backendHealth, fetchConversation, queueCreativeBrief } from './backendClient'
import { requestPhaseLabel, toUiFailure } from './frontendState'
import type { Attachment as DomainAttachment, FrontendRoute } from './domain'
import { Archive, ArrowRight, Bot, Boxes, Check, ChevronDown, ChevronRight, ClipboardCheck, Cloud, Copy, FileAudio, FileImage, FileText, FileVideo, FolderOpen, Globe2, History, ImagePlus, KeyRound, LockKeyhole, MessageCircle, MoreHorizontal, Network, Paperclip, PanelRight, Pencil, Pin, Plus, RefreshCw, Search, Send, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Trash2, Users, WandSparkles, X } from 'lucide-react'

export type ThemeKey = 'graphite'|'light'|'ember'|'forest'|'midnight'|'sand'
type Props = { go:(route:FrontendRoute)=>void; announce:(message:string)=>void; inspect:(kind:string,title:string,detail?:string)=>void; theme:ThemeKey; setTheme:(theme:ThemeKey)=>void; compact:boolean; setCompact:(compact:boolean)=>void; reducedMotion?:boolean; setReducedMotion?:(reduced:boolean)=>void }

type ChatMessage = { id:number; role:'assistant'|'user'; text:string; time:string; media?:boolean }
type Attachment = Omit<DomainAttachment, 'kind' | 'role'> & { id:number; kind:'image'|'video'|'audio'|'file'|'reference'; label:string; role:string }


function Panel({children,className=''}:{children:ReactNode;className?:string}){return <section className={`panel ${className}`}>{children}</section>}
function Head({title,sub,action,click}:{title:string;sub?:string;action?:string;click?:()=>void}){return <div className="section-head"><div><h3>{title}</h3>{sub&&<span>{sub}</span>}</div>{action&&<button className="text-button" onClick={click}>{action}<ArrowRight size={14}/></button>}</div>}
function Pill({children,tone='neutral'}:{children:ReactNode;tone?:string}){return <span className={`status-pill ${tone}`}>{children}</span>}
function Toggle({enabled,onClick,label}:{enabled:boolean;onClick:()=>void;label:string}){return <button className={`refined-toggle ${enabled?'enabled':''}`} onClick={onClick} aria-pressed={enabled}><span className="refined-toggle-track"><i/></span><span>{label}</span></button>}

export function RefinedChat({go,announce,inspect}:Props){
 const [conversation,setConversation]=useState(1);const [message,setMessage]=useState('');const [backendState,setBackendState]=useState<'connecting'|'connected'|'offline'>('connecting');const [messages,setMessages]=useState<ChatMessage[]>([{id:1,role:'assistant',text:'I am ready to help shape the next creative decision. Bring a reference, a constraint, or a direction and I will keep the project context attached.',time:'10:41'},{id:2,role:'user',text:'Create three cinematic food-ad concepts from these references. Keep the opening tactile and the tone direct.',time:'10:42'},{id:3,role:'assistant',text:'I analyzed your references and identified cinematic food advertising, warm directional lighting, fast 2 to 3 second shots, and a direct-response opening hook. I created three original concepts and kept the identity constraints attached.',time:'10:42',media:true}]);const [chatError,setChatError]=useState<unknown|null>(null);const [sending,setSending]=useState(false);const [lastDraft,setLastDraft]=useState<{text:string;attachments:Attachment[];idempotencyKey:string}|null>(null);
 const [attachments,setAttachments]=useState<Attachment[]>([{id:1,kind:'image',label:'Image 1',role:'Character reference'},{id:2,kind:'video',label:'Video 1',role:'Style reference'}]);
 useEffect(()=>{let active=true;let attempts=0;let timer:number|undefined;const check=()=>Promise.all([backendHealth(),fetchConversation()]).then(([,data])=>{if(!active)return;setBackendState('connected');if(data.messages.length)setMessages(data.messages.map((item,index)=>({id:index+1,role:item.role==='user'?'user':'assistant',text:item.content,time:item.created_at.slice(11,16)||'now'}))) }).catch(()=>{attempts+=1;if(active&&attempts<20)timer=window.setTimeout(check,500);else if(active)setBackendState('offline')});check();return()=>{active=false;if(timer)window.clearTimeout(timer)}},[]);
 const [contextOpen,setContextOpen]=useState(true);const [contextTab,setContextTab]=useState('Context');const [modelOpen,setModelOpen]=useState(false);const [model,setModel]=useState('Governor: Auto');const [search,setSearch]=useState('');const [menuFor,setMenuFor]=useState<number|null>(null);const [conversations,setConversations]=useState([{id:1,title:'Citrus at Dusk',preview:'Create three cinematic food-ad concepts...',time:'2m',group:'Today',pinned:true},{id:2,title:'Morning Food Campaign',preview:'Generate three variants for the new menu...',time:'1h',group:'Today',pinned:false},{id:3,title:'Kitchen Light Studies',preview:'Compare the warm edge-light references.',time:'Yesterday',group:'Yesterday',pinned:false},{id:4,title:'Voice direction review',preview:'Keep the CTA conversational and short.',time:'Mon',group:'Previous 7 days',pinned:false}]);
 const filtered=conversations.filter(c=>`${c.title} ${c.preview}`.toLowerCase().includes(search.toLowerCase()));
 const addAttachment=(kind:Attachment['kind'])=>{const n=attachments.length+1;const names={image:`Image ${n}`,video:`Video ${n}`,audio:`Audio ${n}`,file:`File ${n}`,reference:`Reference ${n}`};setAttachments(a=>[...a,{id:n,kind,label:names[kind],role:kind==='reference'?'Reference label':'Unlabeled'}]);announce(`${names[kind]} attached to the local conversation.`)};
 const send=async(retry=false)=>{const draft=retry?lastDraft:null;const text=(draft?.text||message).trim();if(!text||sending)return;const idempotencyKey=draft?.idempotencyKey||`chat-${Date.now()}`;const draftAttachments=draft?.attachments||attachments;if(!retry){setLastDraft({text,attachments:draftAttachments,idempotencyKey});setMessages(m=>[...m,{id:Date.now(),role:'user',text,time:'now'}]);setMessage('')}setChatError(null);setSending(true);try{await queueCreativeBrief(text,draftAttachments,idempotencyKey);setBackendState('connected');announce('Message queued in the local backend.');try{await new Promise(resolve=>setTimeout(resolve,2000));const live=await fetchConversation();if(live.messages.length)setMessages(live.messages.map((item,index)=>({id:index+1,role:item.role==='user'?'user':'assistant',text:item.content,time:item.created_at.slice(11,16)||'now'})));else setMessages(m=>[...m,{id:Date.now()+1,role:'assistant',text:'Brief queued in the local engine room. The live reply is still pending and will appear here after the next refresh.',time:'now'}])}catch{setMessages(m=>[...m,{id:Date.now()+1,role:'assistant',text:'Brief queued in the local engine room. The live reply is still pending and will appear here after the next refresh.',time:'now'}])}}catch(error){setChatError(error);setBackendState('offline');setMessages(m=>[...m,{id:Date.now()+1,role:'assistant',text:'The local backend is unavailable, so this message remains in the renderer draft only.',time:'now'}]);announce('Backend unavailable; draft kept locally.')}finally{setSending(false)}};const chatFailure=chatError?toUiFailure(chatError,'The local message could not be queued.'):null;
 const action=(label:string,route?:FrontendRoute)=>{if(route)go(route);else announce(`${label} staged in the local creative flow.`)};
 const rename=()=>{setConversations(cs=>cs.map(c=>c.id===conversation?{...c,title:`${c.title} / revised`}:c));setMenuFor(null);announce('Conversation renamed locally.')};
 const remove=()=>{setConversations(cs=>cs.filter(c=>c.id!==conversation));setConversation(conversations.find(c=>c.id!==conversation)?.id||1);setMenuFor(null);announce('Conversation archived from the local list.')};
 return <div className="refined-chat-shell"><aside className="chat-history"><div className="chat-history-head"><div><span className="panel-kicker">Creative workspace</span><strong>Conversations</strong></div><button className="primary-button compact-button" onClick={()=>{setMessages([{id:Date.now(),role:'assistant',text:'New conversation ready. What are we making?',time:'now'}]);announce('New local conversation created.')}}><Plus size={14}/> New chat</button></div><div className="chat-search"><Search size={14}/><input placeholder="Search conversations" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="chat-history-list">{['Today','Yesterday','Previous 7 days'].map(group=><div className="chat-history-group" key={group}><span className="chat-group-label">{group}</span>{filtered.filter(c=>c.group===group).map(c=><div className={`conversation-row ${conversation===c.id?'selected':''}`} key={c.id}><button onClick={()=>setConversation(c.id)}><MessageCircle size={14}/><span><b>{c.title}</b><small>{c.preview}</small></span><time>{c.time}</time></button><button className="conversation-menu" onClick={()=>setMenuFor(menuFor===c.id?null:c.id)} aria-label={`Actions for ${c.title}`}><MoreHorizontal size={15}/></button>{menuFor===c.id&&<div className="conversation-popover"><button onClick={rename}><Pencil size={13}/> Rename</button><button onClick={()=>{setConversations(cs=>cs.map(x=>x.id===c.id?{...x,pinned:!x.pinned}:x));setMenuFor(null)}}><Pin size={13}/> {c.pinned?'Unpin':'Pin'}</button><button onClick={remove}><Archive size={13}/> Archive</button><button onClick={remove}><Trash2 size={13}/> Delete</button></div>}</div>)}</div>)}</div><div className="chat-history-foot"><button onClick={()=>announce('Pinned conversations are shown at the top of their local group.')}><Pin size={14}/> Pinned <span>{conversations.filter(c=>c.pinned).length}</span></button><button onClick={()=>go('projects')}><Boxes size={14}/> Project conversations <ChevronRight size={13}/></button><button onClick={()=>go('campaigns')}><Archive size={14}/> Campaign conversations <ChevronRight size={13}/></button></div></aside><section className="chat-main"><div className="chat-main-head"><div><span className="panel-kicker">Northstar Food Stories / Citrus at Dusk</span><h2>{conversations.find(c=>c.id===conversation)?.title||'New conversation'}</h2><span className="chat-status"><i/> {backendState==='connected'?'Backend connected':backendState==='connecting'?'Connecting to engine room…':'Offline-safe local draft'} · Governor context attached</span>{backendState==='offline'&&<div className="chat-offline-notice" role="status"><b>Offline</b><span>The local backend is unreachable, so new messages stay as local drafts and the thread shows the last loaded state.</span></div>}{chatFailure&&<div className="chat-inline-error" role="alert" aria-live="assertive"><b>{requestPhaseLabel(chatFailure.phase)}</b><span>{chatFailure.message}</span>{chatFailure.retryable&&lastDraft&&<button className="secondary-button compact-button" onClick={()=>void send(true)} disabled={sending}><RefreshCw size={13}/> {sending?'Retrying…':'Retry'}</button>}</div>}</div><div className="chat-head-actions"><button className="model-select" onClick={()=>setModelOpen(v=>!v)}><Bot size={14}/><span>{model}</span><ChevronDown size={14}/></button><button className={`icon-button ${contextOpen?'active':''}`} onClick={()=>setContextOpen(v=>!v)} aria-label="Toggle chat context" aria-expanded={contextOpen} title="Toggle context inspector"><PanelRight size={17}/></button></div>{modelOpen&&<div className="model-popover"><span className="panel-kicker">Task routing</span>{['Governor: Auto','General Chat: Auto','Vision: Auto','Creative Planning: Auto','Image Generation: Auto'].map(x=><button key={x} className={model===x?'selected':''} onClick={()=>{setModel(x);setModelOpen(false);announce(`${x} selected locally.`)}}><span>{x.split(':')[0]}</span><Pill tone="positive">Auto</Pill></button>)}</div>}</div><div className="chat-scroll"><div className="chat-thread">{messages.length===0&&<div className="empty-state"><Bot size={22}/><p>No messages in this conversation yet. Send the first brief to start.</p></div>}{messages.map(m=><article className={`chat-message-row ${m.role}`} key={m.id}><div className="chat-author"><span className={`chat-avatar ${m.role}`}><>{m.role==='assistant'?<Bot size={16}/>:<span>FS</span>}</></span><div><b>{m.role==='assistant'?'Flujo':'You'}</b><time>{m.time}</time></div></div><div className="chat-message-body"><p>{m.text}</p>{m.media&&<div className="chat-media-grid">{['Tactile opening','Warm kitchen cut','Direct-response close'].map((x,i)=><button className={`chat-media-card media-${i}`} key={x} onClick={()=>inspect('concept',x,'Generated concept preview is local demo state. Trace its future prompt and evidence through Artifact Lineage.')}><span className="media-card-orb"><Sparkles size={18}/></span><b>{x}</b><small>Concept {i+1} · preview</small><span className="media-card-bar"><i/></span></button>)}</div>}{m.role==='assistant'&&<div className="chat-inline-actions"><button onClick={()=>action('Analyze references','analysis')}>Analyze references</button><button onClick={()=>action('Ask Governor','council')}>Ask Governor</button><button onClick={()=>action('Create Blueprint','blueprint')}>Create Blueprint</button><button onClick={()=>action('Generate 3 concepts')}>Generate 3 concepts</button><button onClick={()=>action('Open QA','qa')}>Open QA</button><button onClick={()=>action('Open lineage','lineage')}>Open lineage</button></div>}</div></article>)}</div></div><div className="chat-composer refined-composer"><div className="composer-attachments">{attachments.map(a=><div className="composer-attachment" key={a.id}><span className={`attachment-icon ${a.kind}`}><AttachmentIcon kind={a.kind}/></span><span><b>{a.label}</b><small>{a.role}</small></span><select aria-label={`Label ${a.label}`} value={a.role} onChange={e=>setAttachments(xs=>xs.map(x=>x.id===a.id?{...x,role:e.target.value}:x))}><option>Unlabeled</option><option>Character reference</option><option>Location reference</option><option>Product reference</option><option>Style reference</option><option>Reference label</option></select><button onClick={()=>setAttachments(xs=>xs.filter(x=>x.id!==a.id))} aria-label={`Remove ${a.label}`}><X size={12}/></button></div>)}</div><textarea value={message} onChange={e=>setMessage(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}}} placeholder="Tell Flujo what you want to create..." rows={3}/><div className="composer-toolbar"><div className="composer-tools"><button onClick={()=>addAttachment('image')}><ImagePlus size={15}/> Image</button><button onClick={()=>addAttachment('video')}><FileVideo size={15}/> Video</button><button onClick={()=>addAttachment('audio')}><FileAudio size={15}/> Audio</button><button onClick={()=>addAttachment('file')}><Paperclip size={15}/> File</button><button onClick={()=>addAttachment('reference')}><Network size={15}/> Reference</button></div><div className="composer-send"><span><SlidersHorizontal size={13}/> {model}</span><button className="primary-button" onClick={()=>void send()} disabled={sending}><Send size={15}/> {sending?'Sending…':'Send'}</button></div></div><small className="composer-note">{backendState==='connected'?'Connected to local engine room · no external provider calls':'Offline-safe mode · drafts stay in this workspace'} · Shift + Enter for a new line</small></div></section>{contextOpen&&<aside className="chat-context"><div className="context-head"><div><span className="panel-kicker">Inspector</span><strong>Chat context</strong></div><button className="icon-button subtle" onClick={()=>setContextOpen(false)} aria-label="Close context"><X size={15}/></button></div><div className="context-tabs">{['Context','Evidence','Entities','Governor','Memory'].map(x=><button className={contextTab===x?'active':''} key={x} onClick={()=>setContextTab(x)}>{x}</button>)}</div>{contextTab==='Context'&&<div className="context-body"><ContextItem label="Project" value="Northstar Food Stories" icon={Boxes}/><ContextItem label="Campaign" value="Citrus at Dusk" icon={Archive}/><ContextItem label="References" value="4 attached / 2 in composer" icon={FileStackIcon}/><ContextItem label="Entities" value="Character 1 · Product 1 · Location 1" icon={Users}/><ContextItem label="Governor" value="Online locally" icon={Bot} tone="positive"/><div className="context-action-list"><button onClick={()=>go('copilot')}><Sparkles size={14}/> Explain this context <ArrowRight size={13}/></button><button onClick={()=>go('memorySources')}><History size={14}/> Review memory sources <ArrowRight size={13}/></button></div></div>}{contextTab==='Evidence'&&<div className="context-body"><ContextEvidence title="Warm directional light" detail="3 supporting references"/><ContextEvidence title="Tactile opening" detail="Genome pattern / v0.8"/><ContextEvidence title="Direct-response hook" detail="Performance signal / local fixture"/><button className="soft-action" onClick={()=>go('evidence')}>Open Evidence Graph <ArrowRight size={14}/></button></div>}{contextTab==='Entities'&&<div className="context-body"><ContextEntity name="Character 1" detail="Canonical reference · 96% consistency"/><ContextEntity name="Product 1" detail="Generation constraint attached"/><ContextEntity name="Location 1" detail="Warm kitchen identity"/><button className="soft-action" onClick={()=>go('entities')}>Open Reference Identity <ArrowRight size={14}/></button></div>}{contextTab==='Governor'&&<div className="context-body"><div className="governor-context"><Bot size={19}/><b>Governor is routing automatically</b><p>Primary: reasoning model · Vision: multimodal model · QA: judge model</p></div><button className="soft-action" onClick={()=>go('governor')}>Open Governor Society <ArrowRight size={14}/></button></div>}{contextTab==='Memory'&&<div className="context-body"><ContextEvidence title="Warm cinematic lighting" detail="Obsidian / Brand / Visual Style.md · 0.94"/><ContextEvidence title="Direct language" detail=".flujo/memory/preferences.md · 0.88"/><button className="soft-action" onClick={()=>go('memorySources')}>Manage memory adapter <ArrowRight size={14}/></button></div>}</aside>}</div>}
function AttachmentIcon({kind}:{kind:Attachment['kind']}){if(kind==='image')return <FileImage size={14}/>;if(kind==='video')return <FileVideo size={14}/>;if(kind==='audio')return <FileAudio size={14}/>;if(kind==='file')return <FileText size={14}/>;return <Network size={14}/>}
function ContextItem({label,value,icon:I,tone}:{label:string;value:string;icon:any;tone?:string}){return <div className="context-item"><span className={`context-item-icon ${tone||''}`}><I size={15}/></span><span><small>{label}</small><b>{value}</b></span></div>}
function ContextEvidence({title,detail}:{title:string;detail:string}){return <button className="context-evidence"><span className="evidence-dot"/><span><b>{title}</b><small>{detail}</small></span><ChevronRight size={14}/></button>}
function ContextEntity({name,detail}:{name:string;detail:string}){return <div className="context-entity"><span className="entity-mini"><Users size={14}/></span><span><b>{name}</b><small>{detail}</small></span><Check size={14}/></div>}
function FileStackIcon(){return <FolderOpen size={15}/>}

type GatewayModel = { provider:string; model_id:string; version:string; capabilities:string[]; modalities:string[]; fallback_group:string; priority:number; status:string }
type ProviderRow = { id:string; name:string; masked_key?:string|null; status:string; last_tested_at?:string|null }
type CredentialRow = { credential_id:string; provider:string; display_name:string; masked_value:string; scope:string; status:string }
type UsageLedger = { events:Array<{ id:string; model_id?:string|null; task?:string|null; requests:number; input_tokens:number; output_tokens:number; estimated_cost:number }>; totals:{ requests:number; input_tokens:number; output_tokens:number; duration_ms:number; estimated_cost:number } }

export function SettingsHub({go,announce,theme,setTheme,compact,setCompact,reducedMotion=false,setReducedMotion}:Props){
 const [section,setSection]=useState('Appearance');const [modelTab,setModelTab]=useState('API Usage');const [providerName,setProviderName]=useState('NVIDIA');const [key,setKey]=useState('');const [fetching,setFetching]=useState(false);
 const [providers,setProviders]=useState<ProviderRow[]>([]);const [credentials,setCredentials]=useState<CredentialRow[]>([]);const [models,setModels]=useState<GatewayModel[]>([]);const [gateway,setGateway]=useState<{simulator_only?:boolean;model_count?:number;status?:string}|null>(null);const [usage,setUsage]=useState<UsageLedger|null>(null);const [activeModels,setActiveModels]=useState<Record<string,boolean>>({});
 const [task,setTask]=useState('Governor');const [routing,setRouting]=useState<Record<string,{primary:string;secondary:string;fallback:string;mode:string}>>({});
 const tasks=['Governor','General Chat','Text Analysis','Vision Analysis','Video Analysis','Audio Analysis','Deep Reasoning','Creative Director','Creative Planning','Image Generation','Image Editing','Video Generation','Voice Generation','Transcription','OCR','Quality Judge','Originality Judge','Safety Judge','Tool Builder','Coding','Fallback / Emergency'];
 const simLabel=gateway===null?'Gateway state unknown':gateway.simulator_only===false?'Live provider path':'Simulator only';
 const loadModelsData=()=>{setFetching(true);Promise.all([backendFetch<GatewayModel[]>('/api/models'),backendFetch<{simulator_only?:boolean;model_count?:number;status?:string}>('/api/gateway/health'),backendFetch<ProviderRow[]>('/api/providers'),backendFetch<CredentialRow[]>('/api/credentials'),backendFetch<UsageLedger>('/api/usage?project_id=project_northstar&limit=200')]).then(([catalog,health,providerRows,credentialRows,ledger])=>{setModels(catalog);setGateway(health);setProviders(providerRows);setCredentials(credentialRows);setUsage(ledger);const label=health.simulator_only===false?'Live provider path':'Simulator only';announce(`Model Gateway catalog loaded from the local backend. ${label}: ${catalog.length} model(s).`)}).catch(()=>announce('Local Model Gateway is unavailable; provider state was not changed.')).finally(()=>setFetching(false))};
 useEffect(()=>{if(section==='Models')loadModelsData()},[section]);
 const addProvider=()=>{if(!key.trim()){announce('Paste an API key first.');return}backendFetch('/api/providers',{method:'POST',body:JSON.stringify({name:providerName,api_key:key.trim()})}).then(()=>{setKey('');announce(`${providerName} saved with a masked key. No external call was made.`);loadModelsData()}).catch(()=>announce('The provider could not be saved.'))};
 const testGateway=()=>{backendFetch<{simulator_only?:boolean;model_count?:number}>('/api/gateway/health').then(health=>{setGateway(health);announce(health.simulator_only===false?`Gateway is live with ${health.model_count||0} model(s).`:`Gateway is simulator-only: no provider credential is configured.`)}).catch(()=>announce('Gateway health is unavailable.'))};
 const testCredential=(credential:CredentialRow)=>{backendFetch(`/api/credentials/${credential.credential_id}/test`,{method:'POST'}).then(()=>announce(`${credential.provider} credential test recorded.`)).catch(()=>announce('The credential test could not be completed.'))};
 const toggleActive=(modelId:string)=>setActiveModels(current=>({...current,[modelId]:!(current[modelId]??true)}));
 const isActive=(m:GatewayModel)=>activeModels[m.model_id]??true;
 const updateRoute=(field:string,value:string)=>setRouting(rs=>({...rs,[task]:{primary:rs[task]?.primary||models[0]?.model_id||'',secondary:rs[task]?.secondary||'',fallback:rs[task]?.fallback||'',mode:rs[task]?.mode||'Auto',[field]:value}}));
 const byModel:Record<string,{requests:number;tokens:number;cost:number}>={};for(const event of usage?.events||[]){const id=event.model_id||'local engine';const entry=byModel[id]||{requests:0,tokens:0,cost:0};entry.requests+=event.requests;entry.tokens+=event.input_tokens+event.output_tokens;entry.cost+=event.estimated_cost;byModel[id]=entry}
 const sections=['General','Appearance','Workspace','Models','Memory','Security','Permissions','Automation','Publishing','Notifications','Setup Assistant','About'];
 const renderModels=()=>{if(modelTab==='API Usage')return <div className="settings-panel-content"><div className="usage-kpis"><div><span>Requests</span><b>{usage?.totals.requests??'--'}</b><small>All recorded usage · local ledger</small></div><div><span>Tokens</span><b>{usage?`${Math.round(((usage.totals.input_tokens+usage.totals.output_tokens)/1000))}k`:'--'}</b><small>Input + output</small></div><div><span>Gateway state</span><b>{simLabel}</b><small>From /api/gateway/health</small></div><div><span>Estimated cost</span><b>{usage?`$${usage.totals.estimated_cost.toFixed(2)}`:'--'}</b><small>Not a real charge</small></div></div><div className="settings-two-col"><Panel><Head title="Provider breakdown" sub="Usage grouped by model from the local ledger"/>{Object.keys(byModel).length===0?<p className="panel-copy">No usage events recorded yet.</p>:Object.entries(byModel).map(([name,stats])=><UsageBar key={name} name={name} value={`${stats.requests} requests`} width={`${Math.min(100,stats.requests*4)}%`} tone="coral"/>)}</Panel><Panel><Head title="Model breakdown" sub="Persisted usage events"/>{Object.keys(byModel).length===0?<p className="panel-copy">No usage events recorded yet.</p>:Object.entries(byModel).slice(0,6).map(([name,stats])=><ModelUsage key={name} name={name} detail={`${stats.requests} requests · ${Math.round(stats.tokens/1000)}k tokens · $${stats.cost.toFixed(2)}`}/>)}</Panel></div></div>;
 if(modelTab==='Providers & API Keys')return <div className="settings-panel-content"><div className="provider-add"><div><span className="panel-kicker">Add provider</span><h2>Provider credentials</h2><p>Keys are masked by the local backend before storage. NVIDIA is the default live provider.</p></div><div className="provider-add-controls"><select value={providerName} onChange={e=>setProviderName(e.target.value)} aria-label="Provider"><option>NVIDIA</option><option>OpenAI</option><option>Google</option><option>Anthropic</option><option>Moonshot</option><option>DeepSeek</option><option>Mistral</option><option>Other</option></select><input type="password" placeholder="Paste API key" value={key} onChange={e=>setKey(e.target.value)}/><button className="primary-button" onClick={addProvider}><Plus size={14}/> Add provider</button></div></div><div className="provider-list">{providers.map(p=><div className="provider-row" key={p.id}><span className="provider-logo"><Cloud size={17}/></span><span><b>{p.name}</b><small>{p.masked_key||'No credential stored'} · {p.status}</small></span><Pill tone={p.status==='configured'?'positive':'neutral'}>{p.status}</Pill><button className="secondary-button compact-button" onClick={testGateway}>Test</button></div>)}{providers.length===0&&!fetching&&<p className="panel-copy">No providers registered yet.</p>}</div><Head title="Stored credentials" sub="Masked values from the secure credential layer"/>{credentials.length===0?<p className="panel-copy">No credentials stored.</p>:<div className="provider-list">{credentials.map(c=><div className="provider-row" key={c.credential_id}><span className="provider-logo"><KeyRound size={17}/></span><span><b>{c.provider}</b><small>{c.display_name} · {c.masked_value} · {c.scope}</small></span><Pill tone={c.status==='active'?'positive':'neutral'}>{c.status}</Pill><button className="secondary-button compact-button" onClick={()=>testCredential(c)}>Test</button></div>)}</div>}<div className="fetch-models-card"><div><span className="panel-kicker">Model discovery</span><b>Fetch all models</b><small>Reads the real Model Gateway catalog. {simLabel}.</small></div><button className="primary-button" onClick={loadModelsData} disabled={fetching}>{fetching?<RefreshCw className="spin" size={14}/>:<Globe2 size={14}/>} {fetching?'Fetching models…':'Fetch all models'}</button></div></div>;
 if(modelTab==='Model Inventory')return <div className="settings-panel-content"><div className="inventory-head"><div><span className="panel-kicker">Model inventory</span><h2>Active model catalog</h2><p>Real catalog from the local Model Gateway. {simLabel}. Inactive models are a local display preference only.</p></div><button className="secondary-button" onClick={loadModelsData} disabled={fetching}><RefreshCw size={14}/> Refresh catalog</button></div>{fetching&&models.length===0?<div className="empty-state"><RefreshCw className="spin" size={22}/><p>Loading the Model Gateway catalog…</p></div>:models.length===0?<div className="empty-state"><Boxes size={22}/><p>No models advertised by the gateway.</p></div>:<div className="inventory-table"><div className="inventory-table-head"><span>Model</span><span>Provider</span><span>Capabilities</span><span>Status</span><span>Active</span></div>{models.map(m=><div className="inventory-row" key={`${m.provider}-${m.model_id}`}><span><b>{m.model_id}</b><small>v{m.version} · {m.modalities.join(' · ')}</small></span><span>{m.provider}</span><span>{m.capabilities.join(' · ')}</span><Pill tone={gateway?.simulator_only===false&&m.status==='healthy'?'positive':'accent'}>{gateway?.simulator_only===false?m.status:'Simulator only'}</Pill><Toggle label={isActive(m)?'ON':'OFF'} enabled={isActive(m)} onClick={()=>toggleActive(m.model_id)}/></div>)}</div>}</div>;
 return <div className="settings-panel-content"><div className="task-routing-head"><div><span className="panel-kicker">AI Per Task</span><h2>Assign responsibility, not just models.</h2><p>Automatic routing stays the default. Manual choices always win when explicitly selected. Routing preferences are local.</p></div><Pill tone="positive"><Bot size={13}/> Governor aware</Pill></div><div className="task-routing-layout"><div className="task-list">{tasks.map(x=><button className={task===x?'active':''} key={x} onClick={()=>setTask(x)}><span>{x}</span><ChevronRight size={14}/></button>)}</div><div className="task-editor"><div className="mode-row"><div><span className="panel-kicker">Selected task</span><h3>{task}</h3></div><div className="segmented"><button className={(routing[task]?.mode||'Auto')==='Auto'?'active':''} onClick={()=>updateRoute('mode','Auto')}>Auto</button><button className={routing[task]?.mode==='Manual'?'active':''} onClick={()=>updateRoute('mode','Manual')}>Manual</button></div></div>{['primary','secondary','fallback'].map(field=><label className="route-field" key={field}><span>{field==='primary'?'Primary':field==='secondary'?'Secondary':'Fallback'}<small>{field==='primary'?'Best available model for this responsibility':field==='secondary'?'Backup when the primary is unavailable':'Emergency route under policy'}</small></span><select value={routing[task]?.[field as 'primary'|'secondary'|'fallback']||''} onChange={e=>updateRoute(field,e.target.value)}><option value="">Auto</option>{models.filter(isActive).map(m=><option key={m.model_id} value={m.model_id}>{m.model_id}</option>)}</select></label>)}<div className="recommended-card"><div><span className="panel-kicker">Recommended</span><b>{models[0]?.model_id||'No catalog loaded'}</b><p>{models[0]?'First model in the live gateway catalog.':'Fetch the catalog to get a recommendation.'}</p></div><button className="secondary-button compact-button" disabled={!models[0]} onClick={()=>{if(models[0]){updateRoute('primary',models[0].model_id);announce('Recommendation accepted locally.')}}}><Check size={13}/> Accept</button></div></div></div></div>};
 return <div className="settings-hub"><aside className="settings-sidebar"><div className="settings-sidebar-title"><Settings2 size={16}/><span>Settings</span></div>{sections.map(x=><button key={x} className={section===x?'active':''} onClick={()=>setSection(x)}>{x}{x==='Models'&&<Pill tone="accent">{models.length||'·'}</Pill>}<ChevronRight size={14}/></button>)}</aside><div className="settings-main"><div className="settings-main-head"><div><span className="panel-kicker">System / Settings</span><h2>{section}</h2><p>{section==='Models'?'Providers, credentials, the live gateway catalog, usage, and task routing.':'Local controls for your creative operating system.'}</p></div><Pill tone="neutral">{section==='Models'?simLabel:'Local controls'}</Pill></div>{section==='Appearance'&&<Appearance theme={theme} setTheme={setTheme} compact={compact} setCompact={setCompact} reducedMotion={reducedMotion} setReducedMotion={setReducedMotion} announce={announce}/>} {section==='Models'&&<><div className="model-tabs">{['API Usage','Providers & API Keys','Model Inventory','AI Per Task'].map(x=><button key={x} className={modelTab===x?'active':''} onClick={()=>setModelTab(x)}>{x}</button>)}</div>{renderModels()}</>} {section==='General'&&<GeneralSettings announce={announce}/>} {section==='Workspace'&&<WorkspaceSettings announce={announce}/>} {section==='Memory'&&<MemorySettings go={go} announce={announce}/>} {section==='Security'&&<SecuritySettings go={go} announce={announce}/>} {section==='Permissions'&&<PermissionsSettings go={go}/>} {section==='Automation'&&<GeneralSettings announce={announce} title="Automation defaults"/>} {section==='Publishing'&&<PublishingSettings announce={announce}/>} {section==='Notifications'&&<NotificationsSettings announce={announce}/>} {section==='Setup Assistant'&&<SetupSettings go={go}/>} {section==='About'&&<AboutSettings/>}</div></div>}

function Appearance({theme,setTheme,compact,setCompact,reducedMotion,setReducedMotion,announce}:{theme:ThemeKey;setTheme:(t:ThemeKey)=>void;compact:boolean;setCompact:(v:boolean)=>void;reducedMotion:boolean;setReducedMotion?:(v:boolean)=>void;announce:(s:string)=>void}){const themes:[ThemeKey,string,string,string][]=[['graphite','Flujo Graphite','Graphite · terracotta · sage','Dark'],['light','Flujo Light','Paper · terracotta · ink','Light'],['ember','Flujo Ember','Charcoal · ember · sand','Dark'],['forest','Flujo Forest','Pine · moss · clay','Dark'],['midnight','Flujo Midnight','Ink · electric blue · lilac','Dark'],['sand','Flujo Sand','Warm paper · clay · moss','Light']];return <div className="appearance-grid"><Panel><Head title="Theme registry" sub="Semantic tokens update the entire application consistently"/><div className="theme-registry">{themes.map(([key,name,detail,mode])=><button className={`theme-option ${theme===key?'selected':''} theme-${key}`} key={key} onClick={()=>{setTheme(key);announce(`${name} applied across Flujo Studio.`)}}><span className="theme-swatch"><i/><i/><i/></span><span><b>{name}</b><small>{detail}</small></span><Pill>{mode}</Pill>{theme===key&&<Check size={15}/>}</button>)}</div></Panel><Panel><Head title="Display behavior" sub="Keep the workspace comfortable for long creative sessions"/><div className="setting-control"><div><b>Density</b><small>Comfortable keeps evidence readable</small></div><div className="segmented"><button className={!compact?'active':''} onClick={()=>setCompact(false)}>Comfortable</button><button className={compact?'active':''} onClick={()=>setCompact(true)}>Compact</button></div></div><div className="setting-control"><div><b>Reduced motion</b><small>Respect operating-system motion preferences</small></div><Toggle label={reducedMotion?'On':'Off'} enabled={reducedMotion} onClick={()=>{setReducedMotion?.(!reducedMotion);announce(`Reduced motion ${!reducedMotion?'enabled':'disabled'} locally.`)}}/></div><div className="token-preview"><span className="panel-kicker">Semantic token preview</span><div><i className="token background"/><i className="token surface"/><i className="token accent"/><i className="token success"/><i className="token warning"/></div></div></Panel></div>}
function GeneralSettings({announce,title='General workspace'}:{announce:(s:string)=>void;title?:string}){return <Panel><Head title={title} sub="Defaults used by future engine-room workflows"/><div className="general-settings-grid">{[['Default project','Northstar Food Stories'],['Default campaign','Citrus at Dusk'],['Generation mode','Balanced'],['Quality threshold','High · 0.82'],['Review mode','Human checkpoint'],['Cost profile','Balanced']].map(([a,b])=><label key={a}><span>{a}</span><select defaultValue={b}><option>{b}</option><option>Economy</option><option>Quality</option><option>Maximum</option><option>Custom</option></select></label>)}</div><button className="primary-button" onClick={()=>announce('General settings saved to local demo state.')}><Check size={14}/> Save defaults</button></Panel>}
function WorkspaceSettings({announce}:{announce:(s:string)=>void}){return <Panel><Head title="Workspace" sub="Choose the stable context every new conversation starts with"/><div className="setting-stack"><SettingLine label="Workspace" detail="Flujo Studio Demo"/><SettingLine label="Default project" detail="Northstar Food Stories"/><SettingLine label="Default campaign" detail="Citrus at Dusk"/><SettingLine label="Default memory scope" detail="Project + permitted memory"/></div><button className="primary-button" onClick={()=>announce('Workspace context saved locally.')}><Check size={14}/> Save workspace</button></Panel>}
function MemorySettings({go,announce}:{go:(r:any)=>void;announce:(s:string)=>void}){return <><Panel><Head title="Memory adapters" sub="Human-readable, scoped, and provenance-visible"/><div className="adapter-setting-grid">{[['Flujo Memory','Markdown + YAML','Enabled'],['Obsidian Adapter','Selected folders only','Optional'],['Project Files','README + brand notes','Scoped'],['Conversation Memory','Current chat context','Scoped'],['User Preferences','Local preference layer','Enabled']].map(([a,b,c])=><div key={a}><span className="adapter-icon"><History size={16}/></span><b>{a}</b><small>{b}</small><Pill tone={c==='Enabled'?'positive':'neutral'}>{c}</Pill></div>)}</div><button className="secondary-button" onClick={()=>go('memorySources')}><History size={14}/> Manage memory sources</button></Panel><Panel><Head title="Provenance" sub="Never show a remembered preference without its source"/><div className="provenance-highlight"><Sparkles size={17}/><div><b>Warm cinematic lighting</b><small>Obsidian / Brand / Visual Style.md · confidence 0.94 · updated Aug 20, 2026</small></div><button className="text-button" onClick={()=>announce('Memory source preview opened locally.')}>Open source <ArrowRight size={13}/></button></div></Panel></>}
function SecuritySettings({go,announce}:{go:(r:any)=>void;announce:(s:string)=>void}){return <><Panel><Head title="Security posture" sub="All host-level capabilities are visibly gated"/><div className="security-setting-grid">{[['Prompt Injection Protection','Enabled','positive'],['External Content Isolation','Enabled','positive'],['Tool Sandbox','Sandbox only','positive'],['Secret Isolation','Masked','positive'],['Host Access','Off by default','warning'],['Network Access','Off by default','warning'],['Publishing Permissions','Human gate','warning']].map(([a,b,c])=><div key={a}><ShieldCheck size={16}/><span><b>{a}</b><small>{b}</small></span><Pill tone={c}>{b}</Pill></div>)}</div></Panel><div className="hero-actions"><button className="secondary-button" onClick={()=>go('permissions')}><LockKeyhole size={14}/> Open Permission Center</button><button className="secondary-button" onClick={()=>announce('Security policy explanation opened locally.')}><Sparkles size={14}/> Explain posture</button></div></>}
function PermissionsSettings({go}:{go:(r:any)=>void}){return <Panel><Head title="Permissions" sub="File, media, process, network, publish, and system access stay separate"/><div className="permission-summary"><Pill tone="positive"><Check size={13}/> Sandbox default</Pill><Pill tone="positive">MEDIA_READ</Pill><Pill tone="positive">MEDIA_WRITE</Pill><Pill tone="critical">SYSTEM_ACCESS denied</Pill></div><button className="primary-button" onClick={()=>go('permissions')}><ShieldCheck size={14}/> Review detailed permissions</button></Panel>}
function PublishingSettings({announce}:{announce:(s:string)=>void}){return <Panel><Head title="Publishing" sub="External release is always gated"/><SettingLine label="Default review gate" detail="Human checkpoint required"/><SettingLine label="Connected accounts" detail="0 connected in demo"/><SettingLine label="Originality check" detail="Required before publish"/><button className="secondary-button" onClick={()=>announce('Publishing defaults saved locally.')}><Check size={14}/> Save publishing defaults</button></Panel>}
function NotificationsSettings({announce}:{announce:(s:string)=>void}){return <Panel><Head title="Notifications" sub="Decide what should interrupt the creative flow"/>{['Governor decisions','System Doctor forecasts','QA blockers','Model drift alerts','Publishing approvals'].map((x,i)=><div className="notification-setting" key={x}><span><b>{x}</b><small>{i<2?'High priority':'Workspace activity'}</small></span><Toggle label={i<4?'On':'Off'} enabled={i<4} onClick={()=>announce(`${x} notification preference toggled locally.`)}/></div>)}</Panel>}
function SetupSettings({go}:{go:(r:any)=>void}){return <Panel><Head title="Setup Assistant" sub="Reopen the first-run flow at any time"/><div className="setup-reopen"><WandSparkles size={21}/><div><b>Workspace onboarding</b><p>Configure appearance, providers, models, memory, defaults, and health checks.</p></div><button className="primary-button" onClick={()=>go('setup')}>Open assistant <ArrowRight size={14}/></button></div></Panel>}
function AboutSettings(){return <Panel><div className="about-block refined-about"><div className="about-mark"><span className="flow-mark"><i/><i/><i/></span></div><h2>Flujo Studio</h2><p>ChatGPT + creative studio + AI production operating system.</p><span className="about-rule"/><b>Analyze. Create. Automate. Learn. Improve.</b><small>Final front-end phase · local demo state · backend-ready screen contracts.</small></div></Panel>}
function SettingLine({label,detail}:{label:string;detail:string}){return <div className="setting-line"><span><b>{label}</b><small>{detail}</small></span><ChevronRight size={14}/></div>}
function UsageBar({name,value,width,tone}:{name:string;value:string;width:string;tone:string}){return <div className="usage-bar"><div><b>{name}</b><small>{value}</small></div><span><i className={tone} style={{width}}/></span></div>}
function ModelUsage({name,detail}:{name:string;detail:string}){return <div className="model-usage"><span className="model-usage-icon"><Bot size={14}/></span><span><b>{name}</b><small>{detail}</small></span><ChevronRight size={14}/></div>}

export function SetupWizard({go,announce,theme,setTheme}:Props){const steps=['Welcome','Workspace','Appearance','Providers','API keys','Fetch models','Activate models','AI per task','Memory','Health check'];const [step,setStep]=useState(0);const [workspace,setWorkspace]=useState('Northstar Food Stories');const [wizardModels,setWizardModels]=useState<string[]>([]);const [wizardFetching,setWizardFetching]=useState(false);const current=steps[step];const fetchWizardModels=()=>{setWizardFetching(true);backendFetch<Array<{model_id:string}>>('/api/models').then(catalog=>{setWizardModels(catalog.map(m=>m.model_id));announce(`Model Gateway returned ${catalog.length} model(s) from the local backend.`)}).catch(()=>announce('The Model Gateway catalog is unavailable.')).finally(()=>setWizardFetching(false))};const persistOnboarding=async(completed:boolean,skipped:boolean)=>{try{await backendFetch('/api/installation/onboarding',{method:'POST',body:JSON.stringify({completed,skipped})})}catch{ /* localStorage fallback below keeps the first-run state deterministic */ }};const next=async()=>{if(step===steps.length-1){localStorage.setItem('flujo-onboarding-complete','true');await persistOnboarding(true,false);announce('Setup complete. Opening Command Center.');go('command')}else setStep(s=>s+1)};const skip=async()=>{localStorage.setItem('flujo-onboarding-skipped','true');await persistOnboarding(false,true);announce('Setup skipped. You can reopen it from Settings.');go('command')};const why:Record<string,string>={Welcome:'Flujo is a creative operating system: the conversation is the front door and the control surfaces keep every decision inspectable.',Workspace:'A workspace keeps projects, campaigns, memory, evidence, and artifacts in one stable context.',Appearance:'Themes use semantic tokens so your entire studio can change mood without rewriting every route.',Providers:'Providers are the doors to the specialist models Flujo will eventually route through the Governor.', 'API keys':'Keys are never shown in full and will later be stored by the secure credential layer.', 'Fetch models':'Fetching discovers the provider catalog so you can decide which models are active.', 'Activate models':'Inactive models will not be suggested to the Governor or task router.', 'AI per task':'AI Per Task assigns responsibility while leaving automatic routing as the default.',Memory:'Memory remains scoped, optional, and provenance-visible. Obsidian is an adapter, not a requirement.','Health check':'The health check confirms the local control plane is ready before the first project begins.'};return <div className="setup-wizard"><div className="setup-wizard-head"><div><span className="panel-kicker">First-run experience</span><h2>Welcome to Flujo Studio</h2><p>Set up the creative operating system in a few deliberate steps. Setup runs locally; provider and model state always comes from the local backend.</p></div><button className="secondary-button" onClick={skip}>Skip for now</button></div><div className="setup-progress">{steps.map((x,i)=><button key={x} className={`${i===step?'active':''} ${i<step?'done':''}`} onClick={()=>i<=step&&setStep(i)}><span>{i<step?<Check size={11}/>:i+1}</span><b>{x}</b></button>)}</div><div className="setup-wizard-grid"><Panel className="setup-step-card"><span className="panel-kicker">Step {step+1} of {steps.length}</span><h2>{current}</h2>{current==='Welcome'&&<><p className="setup-lead">A conversational front door for an inspectable creative flow.</p><div className="setup-visual"><span><MessageCircle size={18}/> Chat</span><ArrowRight size={14}/><span><Bot size={18}/> Governor</span><ArrowRight size={14}/><span><Sparkles size={18}/> Create</span><ArrowRight size={14}/><span><ClipboardCheck size={18}/> Verify</span></div></>}{current==='Workspace'&&<><p>Choose the workspace context Flujo should open by default.</p><label className="wizard-field"><span>Workspace name</span><input value={workspace} onChange={e=>setWorkspace(e.target.value)}/></label><label className="wizard-field"><span>Default project</span><select><option>Northstar Food Stories</option><option>Studio Experiments</option></select></label></>}{current==='Appearance'&&<><p>Choose the mood for your studio. You can change it later in Settings.</p><div className="wizard-theme-grid">{(['graphite','light','ember','forest','midnight','sand'] as ThemeKey[]).map(x=><button className={`wizard-theme theme-${x} ${theme===x?'selected':''}`} key={x} onClick={()=>setTheme(x)}><span/><b>{x==='graphite'?'Graphite':x[0].toUpperCase()+x.slice(1)}</b>{theme===x&&<Check size={13}/>}</button>)}</div></>}{current==='Providers'&&<><p>NVIDIA is the default live provider. Configure its key later in Settings / Models; nothing connects until a credential is stored.</p><div className="wizard-choice-grid">{['NVIDIA','OpenAI','Google','Anthropic','Moonshot','DeepSeek'].map((x,i)=><button className={i<2?'selected':''} key={x}><Cloud size={16}/><b>{x}</b><small>{i<2?'Suggested':'Available later'}</small></button>)}</div></>}{current==='API keys'&&<><p>Credentials will be added in Settings. This step explains the boundary without saving a secret.</p><div className="wizard-callout"><KeyRound size={18}/><div><b>Secure credential boundary</b><small>API keys will later be stored outside ordinary UI state, URLs, chat messages, logs, and analytics.</small></div></div></>}{current==='Fetch models'&&<><p>Ask the local Model Gateway for its real catalog.</p><button className="primary-button" onClick={fetchWizardModels} disabled={wizardFetching}>{wizardFetching?<RefreshCw className="spin" size={14}/>:<RefreshCw size={14}/>} {wizardFetching?'Fetching…':'Fetch models'}</button>{wizardModels.length>0&&<p className="panel-copy">{wizardModels.length} model(s) discovered: {wizardModels.slice(0,4).join(', ')}{wizardModels.length>4?'…':''}</p>}</>}{current==='Activate models'&&<><p>Turn on the models that the Governor may suggest later.</p>{wizardModels.length===0?<p className="panel-copy">Fetch the model catalog in the previous step first.</p>:<div className="wizard-model-list">{wizardModels.map((x,i)=><div key={x}><span><Bot size={14}/><b>{x}</b><small>{i===0?'Default live provider model':'Available'}</small></span><Toggle label="ON" enabled onClick={()=>announce(`${x} activation toggled in local onboarding.`)}/></div>)}</div>}</>}{current==='AI per task'&&<><p>Keep routing automatic or assign a responsibility manually later in Settings → Models.</p><div className="wizard-callout"><SlidersHorizontal size={18}/><div><b>Governor: Auto</b><small>Recommended: {wizardModels[0]||'fetch the catalog first'} · fallback: {wizardModels[1]||'--'}</small></div></div><button className="secondary-button" onClick={()=>go('settings')}>Configure task routing <ArrowRight size={14}/></button></>}{current==='Memory'&&<><p>Choose whether Flujo should use its own memory, permitted project files, or an optional Obsidian adapter.</p><div className="wizard-memory-list">{['Flujo Memory','Project Files','Conversation Memory','Obsidian Adapter'].map((x,i)=><div key={x}><History size={14}/><span><b>{x}</b><small>{i===3?'Optional / folders selected by you':'Scoped local source'}</small></span><Pill tone={i===3?'neutral':'positive'}>{i===3?'Optional':'Enabled'}</Pill></div>)}</div></>}{current==='Health check'&&<><p>Run a local readiness rehearsal. It does not contact providers or publish anything.</p><div className="health-check-list"><span><Check size={13}/> Shell layout ready</span><span><Check size={13}/> Theme tokens ready</span><span><Check size={13}/> Permission defaults safe</span><span><Check size={13}/> Backend connectors disconnected</span></div></>}<div className="wizard-actions"><button className="secondary-button" disabled={step===0} onClick={()=>setStep(s=>Math.max(0,s-1))}>Back</button><button className="primary-button" onClick={next}>{step===steps.length-1?'Complete setup':'Continue'} <ArrowRight size={14}/></button></div></Panel><Panel className="wizard-why"><span className="why-orb"><Sparkles size={18}/></span><span className="panel-kicker">Flujo Copilot / Explain</span><h3>Why does Flujo need this?</h3><p>{why[current]}</p><button className="soft-action" onClick={()=>announce('Copilot explanation copied to the local setup context.')}><Copy size={14}/> Copy explanation</button><div className="wizard-safe"><ShieldCheck size={15}/><span>Local setup only<br/><b>No provider calls</b></span></div></Panel></div></div>}
